import{_ as l,a0 as p,w as o,s as r,ao as c,I as t,x as i,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Linux 中使用 Asciinema 進行錄製和回放終端會話 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中使用 Asciinema 進行錄製和回放終端會話 | LCTT (201705) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中使用 Asciinema 進行錄製和回放終端會話 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中使用 Asciinema 進行錄製和回放終端會話 | LCTT (201705) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201705/20170203 Record and Replay Terminal Session with Asciinema on Linux","title":"如何在 Linux 中使用 Asciinema 進行錄製和回放終端會話","tag":"201705","desc":""},"relativePath":"201705/20170203 Record and Replay Terminal Session with Asciinema on Linux.md","filePath":"[post].md"}'),h={name:"201705/20170203 Record and Replay Terminal Session with Asciinema on Linux.md"};function d(g,s,k,b,u,m){const a=p("Link");return o(),r("div",null,[s[13]||(s[13]=c(`<h1 id="如何在-linux-中使用-asciinema-進行錄製和回放終端會話" tabindex="-1">如何在 Linux 中使用 Asciinema 進行錄製和回放終端會話 <a class="header-anchor" href="#如何在-linux-中使用-asciinema-進行錄製和回放終端會話" aria-label="Permalink to “如何在 Linux 中使用 Asciinema 進行錄製和回放終端會話”">​</a></h1><p><img src="https://linuxconfig.org/images/asciimena-video-example.jpg?58942057" alt=""></p><h3 id="簡介" tabindex="-1">簡介 <a class="header-anchor" href="#簡介" aria-label="Permalink to “簡介”">​</a></h3><p>Asciinema 是一個輕量並且非常高效的終端會話錄製器。使用它可以錄製、回放和分享 JSON 格式的終端會話記錄。與一些桌面錄製器，比如 Recordmydesktop、Simplescreenrecorder、Vokoscreen 或 Kazam 相比，Asciinema 最主要的優點是，它能夠以通過 ASCII 文本以及 ANSI 轉義碼編碼來錄製所有的標準終端輸入、輸出和錯誤信息。</p><p>事實上，即使是很長的終端會話，錄製出的 JSON 格式文件也非常小。另外，JSON 格式使得用户可以利用簡單的文件轉化器，將輸出的 JSON 格式文件嵌入到 HTML 代碼中，然後分享到公共網站或者使用 asciinema 賬户分享到 Asciinema.org 。最後，如果你的終端會話中有一些錯誤，並且你還懂一些 ASCI 轉義碼語法，那麼你可以使用任何編輯器來修改你的已錄製終端會話。</p><p><strong>難易程度：</strong></p><p>很簡單！</p><p><strong>標準終端：</strong></p><ul><li><strong>#</strong> - 給定命令需要以 root 用户權限運行或者使用 <code>sudo</code> 命令</li><li><strong>$</strong> - 給定命令以常規權限用户運行</li></ul><h3 id="從軟件庫安裝" tabindex="-1">從軟件庫安裝 <a class="header-anchor" href="#從軟件庫安裝" aria-label="Permalink to “從軟件庫安裝”">​</a></h3><p>通常， asciinema 可以使用你的發行版的軟件庫進行安裝。但是，如果不可以使用系統的軟件庫進行安裝或者你想安裝最新的版本，那麼，你可以像下面的“從源代碼安裝”部分所描述的那樣，使用 Linuxbrew 包管理器來執行 Asciinema 安裝。</p><p><strong>在 Arch Linux 上安裝：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pacman -S asciinema</span></span></code></pre></div><p><strong>在 Debian 上安裝：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt install asciinema</span></span></code></pre></div><p><strong>在 Ubuntu 上安裝：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install asciinema</span></span></code></pre></div><p><strong>在 Fedora 上安裝：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install asciinema</span></span></code></pre></div><h3 id="從源代碼安裝" tabindex="-1">從源代碼安裝 <a class="header-anchor" href="#從源代碼安裝" aria-label="Permalink to “從源代碼安裝”">​</a></h3><p>最簡單並且值得推薦的方式是使用 Linuxbrew 包管理器，從源代碼安裝最新版本的 Asciinema 。</p><h4 id="前提條件" tabindex="-1">前提條件 <a class="header-anchor" href="#前提條件" aria-label="Permalink to “前提條件”">​</a></h4><p>下面列出的前提條件是安裝 Linuxbrew 和 Asciinema 需要滿足的依賴關係：</p><ul><li>git</li><li>gcc</li><li>make</li><li>ruby</li></ul><p>在安裝 Linuxbrew 之前，請確保上面的這些包都已經安裝在了你的 Linux 系統中。</p><p><strong>在 Arch Linux 上安裝 ruby：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># pacman -S git gcc make ruby</span></span></code></pre></div><p><strong>在 Debian 上安裝 ruby：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># apt install git gcc make ruby</span></span></code></pre></div><p><strong>在 Ubuntu 上安裝 ruby：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install git gcc make ruby</span></span></code></pre></div><p><strong>在 Fedora 上安裝 ruby：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install git gcc make ruby</span></span></code></pre></div><p><strong>在 CentOS 上安裝 ruby：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># yum install git gcc make ruby</span></span></code></pre></div><h4 id="安裝-linuxbrew" tabindex="-1">安裝 Linuxbrew <a class="header-anchor" href="#安裝-linuxbrew" aria-label="Permalink to “安裝 Linuxbrew”">​</a></h4><p>Linuxbrew 包管理器是蘋果的 MacOS 操作系統很受歡迎的 Homebrew 包管理器的一個復刻版本。還沒發佈多久，Homebrew 就以容易使用而著稱。如果你想使用 Linuxbrew 來安裝 Asciinema，那麼，請運行下面命令在你的 Linux 版本上安裝 Linuxbrew：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ruby -e &quot;$(curl -fsSL https://raw.githubusercontent.com/Linuxbrew/install/master/install)&quot;</span></span></code></pre></div><p>現在，Linuxbrew 已經安裝到了目錄 <code>$HOME/.linuxbrew/</code> 下。剩下需要做的就是使它成為可執行 <code>PATH</code> 環境變量的一部分。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;export PATH=&quot;$HOME/.linuxbrew/bin:$PATH&quot;&#39; &gt;&gt;~/.bash_profile</span></span>
<span class="line"><span>$ . ~/.bash_profile</span></span></code></pre></div><p>為了確認 Linuxbrew 是否已經安裝好，你可以使用 <code>brew</code> 命令來查看它的版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ brew --version</span></span>
<span class="line"><span>Homebrew 1.1.7</span></span>
<span class="line"><span>Homebrew/homebrew-core (git revision 5229; last commit 2017-02-02)</span></span></code></pre></div><h4 id="安裝-asciinema" tabindex="-1">安裝 Asciinema <a class="header-anchor" href="#安裝-asciinema" aria-label="Permalink to “安裝 Asciinema”">​</a></h4><p>安裝好 Linuxbrew 以後，安裝 Asciinema 就變得無比容易了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ brew install asciinema</span></span></code></pre></div><p>檢查 Asciinema 是否安裝正確：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ asciinema --version</span></span>
<span class="line"><span>asciinema 1.3.0</span></span></code></pre></div><h3 id="錄製終端會話" tabindex="-1">錄製終端會話 <a class="header-anchor" href="#錄製終端會話" aria-label="Permalink to “錄製終端會話”">​</a></h3><p>經過一番辛苦的安裝工作以後，是時候來幹一些有趣的事情了。Asciinema 是一個非常容易使用的軟件。事實上，目前的 1.3 版本只有很少的幾個可用命令列選項，其中一個是 <code>--help</code> 。</p><p>我們首先使用 <code>rec</code> 選項來錄製終端會話。下面的命令將會開始錄製終端會話，之後，你將會有一個選項來丟棄已錄製記錄或者把它上傳到 asciinema.org 網站以便將來參考。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ asciinema rec</span></span></code></pre></div><p>運行上面的命令以後，你會注意到， Asciinema 已經開始錄製終端會話了，你可以按下 <code>CTRL+D</code> 快捷鍵或執行 <code>exit</code> 命令來停止錄製。如果你使用的是 Debian/Ubuntu/Mint Linux 系統，你可以像下面這樣嘗試進行第一次 asciinema 錄製：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ su</span></span>
<span class="line"><span>Password:</span></span>
<span class="line"><span># apt install sl</span></span>
<span class="line"><span># exit</span></span>
<span class="line"><span>$ sl</span></span></code></pre></div><p>一旦輸入最後一個 <code>exit</code> 命令以後，將會詢問你：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ exit</span></span>
<span class="line"><span>~ Asciicast recording finished.</span></span>
<span class="line"><span>~ Press &lt;Enter&gt; to upload, &lt;Ctrl-C&gt; to cancel.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>https://asciinema.org/a/7lw94ys68gsgr1yzdtzwijxm4</span></span></code></pre></div><p>如果你不想上傳你的私密命令列技巧到 asciinema.org 網站，那麼有一個選項可以把 Asciinema 記錄以 JSON 格式保存為本地文件。比如，下面的 asciinema 記錄將被存為 <code>/tmp/my_rec.json</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ asciinema rec /tmp/my_rec.json</span></span></code></pre></div><p>另一個非常有用的 asciinema 特性是時間微調。如果你的鍵盤輸入速度很慢，或者你在進行多任務，輸入命令和執行命令之間的時間會比較長。Asciinema 會記錄你的實時按鍵時間，這意味着每一個停頓都將反映在最終視頻的長度上。可以使用 <code>-w</code> 選項來縮短按鍵的時間間隔。比如，下面的命令將按鍵的時間間隔縮短為 0.2 秒：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ asciinema rec -w 0.2</span></span></code></pre></div><h3 id="回放已錄製終端會話" tabindex="-1">回放已錄製終端會話 <a class="header-anchor" href="#回放已錄製終端會話" aria-label="Permalink to “回放已錄製終端會話”">​</a></h3><p>有兩種方式可以來回放已錄製會話。第一種方式是直接從 asciinema.org 網站上播放終端會話。這意味着，你之前已經把錄製會話上傳到了 asciinema.org 網站，並且需要提供有效鏈接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ asciinema play https://asciinema.org/a/7lw94ys68gsgr1yzdtzwijxm4</span></span></code></pre></div><p>另外，你也可以使用本地存儲的 JSON 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ asciinema play /tmp/my_rec.json</span></span></code></pre></div><p>如果要使用 <code>wget</code> 命令來下載之前的上傳記錄，只需在鏈接的後面加上 <code>.json</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget -q -O steam_locomotive.json https://asciinema.org/a/7lw94ys68gsgr1yzdtzwijxm4.json</span></span>
<span class="line"><span>$ asciinema play steam_locomotive.json</span></span></code></pre></div><h3 id="將視頻嵌入-html" tabindex="-1">將視頻嵌入 HTML <a class="header-anchor" href="#將視頻嵌入-html" aria-label="Permalink to “將視頻嵌入 HTML”">​</a></h3><p>最後，asciinema 還帶有一個獨立的 JavaScript 播放器。這意味者你可以很容易的在你的網站上分享終端會話記錄。下面，使用一段簡單的 <code>index.html</code> 代碼來説明這個方法。首先，下載所有必要的東西：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /tmp/</span></span>
<span class="line"><span>$ mkdir steam_locomotive</span></span>
<span class="line"><span>$ cd steam_locomotive/</span></span>
<span class="line"><span>$ wget -q -O steam_locomotive.json https://asciinema.org/a/7lw94ys68gsgr1yzdtzwijxm4.json</span></span>
<span class="line"><span>$ wget -q https://github.com/asciinema/asciinema-player/releases/download/v2.4.0/asciinema-player.css</span></span>
<span class="line"><span>$ wget -q https://github.com/asciinema/asciinema-player/releases/download/v2.4.0/asciinema-player.js</span></span></code></pre></div><p>之後，創建一個新的包含下面這些內容的 <code>/tmp/steam_locomotive/index.html</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;html&gt;</span></span>
<span class="line"><span>&lt;head&gt;</span></span>
<span class="line"><span>  &lt;link rel=&quot;stylesheet&quot; type=&quot;text/css&quot; href=&quot;./asciinema-player.css&quot; /&gt;</span></span>
<span class="line"><span>&lt;/head&gt;</span></span>
<span class="line"><span>&lt;body&gt;</span></span>
<span class="line"><span>  &lt;asciinema-player src=&quot;./steam_locomotive.json&quot; cols=&quot;80&quot; rows=&quot;24&quot;&gt;&lt;/asciinema-player&gt;</span></span>
<span class="line"><span>  &lt;script src=&quot;./asciinema-player.js&quot;&gt;&lt;/script&gt;</span></span>
<span class="line"><span>&lt;/body&gt;</span></span>
<span class="line"><span>&lt;/html&gt;</span></span></code></pre></div><p>完成以後，打開你的網頁瀏覽器，按下 <code>CTRL+O</code> 來打開新創建的 <code>/tmp/steam_locomotive/index.html</code> 文件。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>正如前面所説的，使用 asciinema 錄製器來錄製終端會話最主要的優點是它的輸出文件非常小，這使得你的視頻很容易分享出去。上面的例子產生了一個包含 58472 個字符的文件，它是一個只有 58 KB 大 小的 22 秒終端會話視頻。如果我們查看輸出的 JSON 文件，會發現甚至這個數字已經非常大了，這主要是因為一個 “蒸汽機車” 已經跑過了終端。這個長度的正常終端會話一般會產生一個更小的輸出文件。</p><p>下次，當你想要在一個論壇上詢問關於 Linux 配置的問題，並且很難描述你的問題的時候，只需運行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ asciinema rec</span></span></code></pre></div><p>然後把最後的鏈接貼到論壇的帖子裏。</p><h3 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to “故障排除”">​</a></h3><h4 id="在-utf-8-環境下運行-asciinema" tabindex="-1">在 UTF-8 環境下運行 asciinema <a class="header-anchor" href="#在-utf-8-環境下運行-asciinema" aria-label="Permalink to “在 UTF-8 環境下運行 asciinema”">​</a></h4><p>錯誤信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>asciinema needs a UTF-8 native locale to run. Check the output of \`locale\` command.</span></span></code></pre></div><p>解決方法： 生成並導出 UTF-8 語言環境。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ localedef -c -f UTF-8 -i en_US en_US.UTF-8</span></span>
<span class="line"><span>$ export LC_ALL=en_US.UTF-8</span></span></code></pre></div><hr>`,84)),t("p",null,[s[1]||(s[1]=i("via: ",-1)),e(a,{href:"https://linuxconfig.org/record-and-replay-terminal-session-with-asciinema-on-linux"},{default:n(()=>[...s[0]||(s[0]=[i("https://linuxconfig.org/record-and-replay-terminal-session-with-asciinema-on-linux",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=i("作者：",-1)),e(a,{href:"https://linuxconfig.org/record-and-replay-terminal-session-with-asciinema-on-linux"},{default:n(()=>[...s[2]||(s[2]=[i("Lubos Rendek",-1)])]),_:1}),s[6]||(s[6]=i(" 譯者：",-1)),e(a,{href:"https://github.com/ucasFL"},{default:n(()=>[...s[3]||(s[3]=[i("ucasFL",-1)])]),_:1}),s[7]||(s[7]=i(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[4]||(s[4]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=i("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[8]||(s[8]=[i("LCTT",-1)])]),_:1}),s[11]||(s[11]=i(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:n(()=>[...s[9]||(s[9]=[i("Linux中國",-1)])]),_:1}),s[12]||(s[12]=i(" 榮譽推出",-1))])])}const C=l(h,[["render",d]]);export{x as __pageData,C as default};
